INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter Binärpräfixen?', 2, '[{"text": "Maßeinheiten für Binärsysteme", "correct": true, "because": "Basieren auf 2^10"}, {"text": "Dateiformate", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Binärpräfixe?', 3, '[{"text": "Präzise Speichergrößenangabe", "correct": true, "because": "Unterschied zu Dezimalsystem"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein technisches Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Binärpräfixe gibt es?', 5, '[{"text": "Kibi (Ki)", "correct": true, "because": "2^10"}, {"text": "Mebi (Mi)", "correct": true, "because": "2^20"}, {"text": "Gibi (Gi)", "correct": true, "because": "2^30"}, {"text": "Kilo (k)", "correct": false, "because": "Dezimalpräfix"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Kibibyte entspricht 1024 Bytes. b) Es ist dasselbe wie ein Kilobyte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kilobyte ist 1000 Bytes"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Binärpräfixen?', 4, '[{"text": "Binärbasis (2^10)", "correct": false, "because": "Grundlage"}, {"text": "Einheitenkonvertierung", "correct": false, "because": "Wichtig für Berechnungen"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mebibyte 1024 Kibibytes entspricht?', 2, '[{"text": "Ja", "correct": true, "because": "2^20 = 1024 * 2^10"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Binärpräfix steht für 2^30?', 3, '[{"text": "Gibi", "correct": true, "because": "2^30 Bytes"}, {"text": "Mega", "correct": false, "because": "Dezimalpräfix"}, {"text": "Tera", "correct": false, "because": "Dezimalpräfix"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Arbeit mit Binärpräfixen?', 5, '[{"text": "Umrechnung in Bytes", "correct": true, "because": "Präzise Angaben"}, {"text": "Speichergrößenberechnung", "correct": true, "because": "Praktische Anwendung"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Binärpräfixe sind präziser als Dezimalpräfixe. b) Sie werden nur in Datenbanken genutzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überall in IT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Binärpräfixen unwichtig?', 4, '[{"text": "Binärbasis", "correct": false, "because": "Grundlage"}, {"text": "Umrechnung", "correct": false, "because": "Notwendig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Gibibyte größer als ein Mebibyte?', 2, '[{"text": "Ja", "correct": true, "because": "2^30 > 2^20"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Binärpräfixe für Fachinformatiker?', 4, '[{"text": "Genauigkeit", "correct": true, "because": "Präzise Speicherangaben"}, {"text": "Einheitlichkeit", "correct": true, "because": "Standard in IT"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Binärpräfixe nur für Speichergrößen sind. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Primär für Speicher"}, {"text": "Nein", "correct": false, "because": "Hauptanwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Binärpräfixen?', 3, '[{"text": "Präzision", "correct": true, "because": "Exakte Angaben"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Kibibyte ist 1024 Bytes. b) Es ist dasselbe wie ein Kilobyte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kilobyte = 1000 Bytes"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Verwechslung von Binär- und Dezimalpräfixen?', 5, '[{"text": "Ungenaue Speicherangaben", "correct": true, "because": "Verwirrung"}, {"text": "Fehler bei Berechnungen", "correct": true, "because": "Falsche Werte"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Binärpräfixen?', 3, '[{"text": "Korrekte Anwendung", "correct": true, "because": "Präzision sicherstellen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Binärpräfix in Spezifikationen genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Technische Dokumentation"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Binärpräfix entspricht 2^40?', 4, '[{"text": "Tebi", "correct": true, "because": "2^40 Bytes"}, {"text": "Gibi", "correct": false, "because": "2^30"}, {"text": "Mebi", "correct": false, "because": "2^20"}]');
